  const topics = [...new Set(items.filter((item) => open(item) && !item.blocking).map((item) => item.topic))];
  const bySeverity = (a, b) => severityOrder2.indexOf(a.severity ?? "") - severityOrder2.indexOf(b.severity ?? "");
